-- Function: public.sp_sync_parent_external_login
-- Backup generated on 2026-11-11 09:05:59

CREATE OR REPLACE PROCEDURE public.sp_sync_parent_external_login(IN p_provider character varying, IN p_provider_key character varying, IN p_email character varying, IN p_first_name character varying, IN p_last_name character varying, IN p_display_name character varying, IN p_default_tenant_id uuid, IN p_default_org_id uuid, INOUT io_user_id uuid DEFAULT NULL::uuid, INOUT io_tenant_id uuid DEFAULT NULL::uuid, INOUT io_is_active boolean DEFAULT NULL::boolean)  LANGUAGE plpgsql AS $procedure$ DECLARE     v_existing_user_id UUID;     v_existing_tenant_id UUID;     v_existing_is_active BOOLEAN;     v_parent_role_id UUID; BEGIN     -- Check if provider key already linked     SELECT user_id INTO v_existing_user_id     FROM user_external_logins     WHERE provider = p_provider AND provider_key = p_provider_key;      IF v_existing_user_id IS NOT NULL THEN         SELECT id, tenant_id, is_active         INTO io_user_id, io_tenant_id, io_is_active         FROM users         WHERE id = v_existing_user_id;         RETURN;     END IF;      -- Check if user exists by normalized email     SELECT id, tenant_id, is_active     INTO v_existing_user_id, v_existing_tenant_id, v_existing_is_active     FROM users     WHERE normalized_email = UPPER(p_email)     LIMIT 1;      IF v_existing_user_id IS NOT NULL THEN         -- Reactivate if previously inactive or has active enrolled child         UPDATE users         SET is_active = TRUE, email_confirmed = TRUE, updated_at = NOW()         WHERE id = v_existing_user_id;          INSERT INTO user_external_logins (provider, provider_key, user_id, created_at)         VALUES (p_provider, p_provider_key, v_existing_user_id, NOW())         ON CONFLICT (provider, provider_key) DO NOTHING;          io_user_id := v_existing_user_id;         io_tenant_id := v_existing_tenant_id;         io_is_active := TRUE;     ELSE         -- Auto-create new parent user account         io_user_id := gen_random_uuid();         io_tenant_id := p_default_tenant_id;         io_is_active := TRUE;          INSERT INTO users (             id, tenant_id, email, normalized_email, email_confirmed,             first_name, last_name, display_name, password_hash, security_stamp, is_active, created_at, updated_at         ) VALUES (             io_user_id, io_tenant_id, p_email, UPPER(p_email), TRUE,             p_first_name, p_last_name, p_display_name, '', gen_random_uuid()::varchar, TRUE, NOW(), NOW()         );          INSERT INTO user_external_logins (provider, provider_key, user_id, created_at)         VALUES (p_provider, p_provider_key, io_user_id, NOW())         ON CONFLICT (provider, provider_key) DO NOTHING;          -- Ensure organization membership         INSERT INTO organization_memberships (user_id, organization_id, tenant_id, status, created_at, updated_at)         VALUES (io_user_id, p_default_org_id, io_tenant_id, 'Active', NOW(), NOW())         ON CONFLICT (user_id, organization_id) DO UPDATE SET status = 'Active';          -- Assign Parent role         SELECT id INTO v_parent_role_id         FROM roles         WHERE name = 'Parent' AND tenant_id = io_tenant_id         LIMIT 1;          IF v_parent_role_id IS NOT NULL THEN             INSERT INTO user_organization_roles (user_id, role_id, organization_id, tenant_id)             VALUES (io_user_id, v_parent_role_id, p_default_org_id, io_tenant_id)             ON CONFLICT DO NOTHING;         END IF;          -- Ensure person record         INSERT INTO persons (id, tenant_id, user_id, first_name, last_name, relationship, email, preferred_language, has_portal_access, receives_daily_updates, receives_photos)         SELECT gen_random_uuid(), io_tenant_id, io_user_id, p_first_name, p_last_name, 'Parent', p_email, 'English', TRUE, TRUE, TRUE         WHERE NOT EXISTS (SELECT 1 FROM persons WHERE user_id = io_user_id);     END IF; END; $procedure$ ;
